-- À exécuter UNE FOIS dans Supabase > SQL Editor (après supabase.sql déjà exécuté)
alter table profiles add column if not exists username text unique;
update profiles set username=split_part(email,'@',1) where username is null;
alter table presences add column if not exists arrivee time, add column if not exists fin time;
alter table paiements add column if not exists numero bigint generated by default as identity;

create or replace function audit() returns trigger language plpgsql security definer set search_path=public as $$
begin insert into audit_log(user_email,tab,action,row_data) values(coalesce((select username from profiles where id=auth.uid()),auth.jwt()->>'email'),tg_table_name,tg_op,to_jsonb(new)); return new; end $$;
create or replace function handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$
begin insert into profiles(id,email,nom,username) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'nom',new.email),coalesce(new.raw_user_meta_data->>'username',split_part(new.email,'@',1))); return new; end $$;
create or replace function email_of(u text) returns text language sql security definer set search_path=public as $$ select email from profiles where lower(username)=lower(u) limit 1 $$;
grant execute on function email_of(text) to anon,authenticated;
create or replace function admin_update(uid uuid,uname text,fname text) returns void language plpgsql security definer set search_path=public as $$
begin if not is_super() then raise exception 'interdit'; end if; update profiles set username=uname,nom=fname where id=uid; end $$;
create or replace function admin_set_password(uid uuid,pw text) returns void language plpgsql security definer set search_path=public as $$
begin if not is_super() then raise exception 'interdit'; end if; update auth.users set encrypted_password=extensions.crypt(pw,extensions.gen_salt('bf')) where id=uid; update profiles set must_change=true where id=uid; end $$;
create or replace function admin_delete(uid uuid) returns void language plpgsql security definer set search_path=public as $$
begin if not is_super() or uid=auth.uid() then raise exception 'interdit'; end if; delete from auth.users where id=uid; end $$;
